item.content:encoded:
.single-product .product_title{ font-family: sans-serif;
font-size:38px !important;
padding-bottom: 0px;
margin-bottom: 0px;
}
.single-product .product-info .short-description{
font-size: 30px !important;
}
.product-subtitle{
font-size: 18px;
padding-top: 0px;
margin-top: 0px;
}
h2.yikes-custom-woo-tab-title {
     display: none;
}
.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {
		margin-left: 5;
		margin-right: 5;
}
.woocommerce ul.products li.product, .woocommerce-page ul.products li.product {
		margin-left: 0;
		margin-right: 0;
}	
.woocommerce div.product {
    padding-left: 14%;						
		padding-right: 14%;
}
.woocommerce div.product .woocommerce-tabs .panel {
    padding-left: 5px;
		padding-bottom: 10px;
}
